import{_ as l,H as a,f as i,i as t}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"02｜Claude Code 进来后：哪一步变了，哪一步没变？","description":"","frontmatter":{},"headers":[{"level":2,"title":"分工别搞错了","slug":"分工别搞错了","link":"#分工别搞错了","children":[{"level":3,"title":"第一档：AI 主导，做 80%","slug":"第一档-ai-主导-做-80","link":"#第一档-ai-主导-做-80","children":[]},{"level":3,"title":"第二档：人机对半，AI 做 50%","slug":"第二档-人机对半-ai-做-50","link":"#第二档-人机对半-ai-做-50","children":[]},{"level":3,"title":"第三档：人主导，AI 做 20% 或更少","slug":"第三档-人主导-ai-做-20-或更少","link":"#第三档-人主导-ai-做-20-或更少","children":[]}]},{"level":2,"title":"最危险的情况是什么","slug":"最危险的情况是什么","link":"#最危险的情况是什么","children":[]},{"level":2,"title":"那 20% 就是你的位置","slug":"那-20-就是你的位置","link":"#那-20-就是你的位置","children":[]},{"level":2,"title":"AI 改变的不是链路，是节奏","slug":"ai-改变的不是链路-是节奏","link":"#ai-改变的不是链路-是节奏","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级老项目改造实战/02｜ClaudeCode进来后：哪一步变了，哪一步没变？.md","filePath":"ClaudeCode企业级老项目改造实战/02｜ClaudeCode进来后：哪一步变了，哪一步没变？.md","lastUpdated":1779815445000}'),o={name:"ClaudeCode企业级老项目改造实战/02｜ClaudeCode进来后：哪一步变了，哪一步没变？.md"};function r(p,e,n,A,s,d){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="_02-claude-code-进来后-哪一步变了-哪一步没变" tabindex="-1">02｜Claude Code 进来后：哪一步变了，哪一步没变？ <a class="header-anchor" href="#_02-claude-code-进来后-哪一步变了-哪一步没变" aria-label="Permalink to &quot;02｜Claude Code 进来后：哪一步变了，哪一步没变？&quot;">​</a></h1><p>你好，我是 Robert。</p><p>上一讲讲了九步真实链路。学完那一讲你可能会想： <strong>链路是清楚了，那 AI 进来之后，每一步我到底该让它做多少、自己守多少？</strong> 这一讲就回答这个问题。</p><p>读完这一讲，你会获得一张人机分工图。面对任何一个陌生老项目的任何一步，你都能快速判断：这一步应该让 Claude Code 冲在前面，还是应该自己在前头、AI 辅助。</p><h2 id="分工别搞错了" tabindex="-1">分工别搞错了 <a class="header-anchor" href="#分工别搞错了" aria-label="Permalink to &quot;分工别搞错了&quot;">​</a></h2><p>先澄清一件事， <strong>分工不是“会不会用 AI”，是“什么时候用、用多少”</strong>。很多人用 Claude Code 用得不顺，不是他们不会用，是分工搞错了。具体有两种典型错误：</p><p>一种是 <strong>过度依赖：</strong> 把 AI 当成一个什么都能干的外包。项目拿到手第一件事就让 AI 改代码，出了问题再怪 AI 不靠谱。这种用法的本质是把 AI 当成“能自动理解项目的开发者”，但开篇词里我说过，AI 是上下文缺失的实习生，你不传递，它就是瞎的。</p><p>另一种是 <strong>过度保守：</strong> AI 能做的事也不让它做。还在一行一行手动读 README、手动画架构图、手动数接口。最后确实改得稳，但速度慢到没有优势，等于白用了工具。</p><p>真正稳的工程师在这两端之间找平衡。他们对九步链路里每一步都有清晰的认知：哪一步 AI 冲在前面，哪一步自己在前头、AI 辅助。这一讲把这张图给你。把 01 讲的九步拿出来，按 AI 能承担的比例归成三档。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/974095/fc7cb58e9dd638ed69639fdecc0efba7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/974095/fc7cb58e9dd638ed69639fdecc0efba7.png" alt=""></a></p><h3 id="第一档-ai-主导-做-80" tabindex="-1">第一档：AI 主导，做 80% <a class="header-anchor" href="#第一档-ai-主导-做-80" aria-label="Permalink to &quot;第一档：AI 主导，做 80%&quot;">​</a></h3><p>这一档的共同点是： <strong>内容都写在代码或公开文档里，AI 能直接读到</strong>。</p><ul><li><p>翻资料（第 2 步）：AI 读 README、wiki、Confluence、jira 比你快十倍</p></li><li><p>浏览代码结构（第 3 步）：让 AI 扫一遍仓库，生成一张模块图、数据流图</p></li><li><p>访接口（第 5 步）：让 AI 从代码里梳理出所有接口清单 + curl 示例</p></li></ul><p>这几步你基本可以放手。让 AI 做初稿，你花几分钟校一眼。有问题就让它“把这个地方再细化一下”，没问题就往下走。</p><h3 id="第二档-人机对半-ai-做-50" tabindex="-1">第二档：人机对半，AI 做 50% <a class="header-anchor" href="#第二档-人机对半-ai-做-50" aria-label="Permalink to &quot;第二档：人机对半，AI 做 50%&quot;">​</a></h3><p>这一档的共同点是： <strong>AI 能做一半，但另一半需要人的判断或人脉</strong>。</p><ul><li><p>找人聊（第 1 步）：AI 能帮你整理疑点清单、草拟要问的问题，但去问谁、怎么问、怎么把答案串起来，是你的事</p></li><li><p>搭环境跑起来（第 4 步）：AI 能帮你写启动脚本、调依赖版本，但公司内部的 VPN、数据库授权、服务调通，多数情况下 AI 不知道</p></li><li><p>带疑点深挖（第 6 步）：AI 能扫描代码给你找调用链路，但“这段逻辑为什么这样写”的答案经常只有问到人才能得到</p></li><li><p>画核心链路（第 7 步）：AI 能给你出一张不错的 Mermaid 图，但关键的业务约定、历史坑点要靠你补进去</p></li><li><p>动手改（第 8 步）：AI 能把你描述的改造写成代码、写测试，但“方案 A 还是 B”、“这段要不要重构”、“边界条件怎么处理”这些决策是你要做的</p></li></ul><p>这一档是大家最常遇到的情况，因为老项目里很少有一点信息都读不到的情况。所以整门课大部分内容会围绕这一档展开。讲你和 AI 怎么配合、提示词怎么写、什么时候该打断它、什么时候该让它继续。</p><h3 id="第三档-人主导-ai-做-20-或更少" tabindex="-1">第三档：人主导，AI 做 20% 或更少 <a class="header-anchor" href="#第三档-人主导-ai-做-20-或更少" aria-label="Permalink to &quot;第三档：人主导，AI 做 20% 或更少&quot;">​</a></h3><p>这一档的共同点是： <strong>答案不在代码里，在人的脑子里或工程判断里</strong>。</p><ul><li><p>判断哪些代码不能动：像 01 讲那个“// 不要删，某某对接方需要”的注释，AI 看不出它背后意味着什么，只有经历过那次 incident 的人知道</p></li><li><p>判断对接方是谁、对接方的诉求变了没有：AI 可能猜得到对接方叫什么，但猜不到最近有没有人改动他们的调用</p></li><li><p>最终验收（第 9 步）：跑了几个业务场景、看了主流程、找人 review，这件事 AI 能帮你列 checklist，但“按下上线按钮”这个动作必须是你来做</p></li><li><p>上线前的风险判断：对回滚成本、灰度方案、影响面的判断，AI 能给参考，但决策权在你</p></li></ul><p>这一档要的不是更强的 AI，是更清醒的你。</p><h2 id="最危险的情况是什么" tabindex="-1">最危险的情况是什么 <a class="header-anchor" href="#最危险的情况是什么" aria-label="Permalink to &quot;最危险的情况是什么&quot;">​</a></h2><p>在我看来，最危险的情况是： <strong>AI 做了 80% 后，你却把剩下的 20% 当成 0，当个甩手掌柜</strong>。现在给你一个更具体的场景，感受一下三档分工有多重要。</p><p>回到 01 讲那个接手 xxx-scheduler 的场景。假设这次不是人在干，是有 AI 辅助的版本。把仓库给 Claude Code，让它帮忙读 README、梳理代码结构、数接口、列数据表。AI 做得很快、很好，半小时之内就拿到了一份相当完整的项目摘要。</p><p>看着那份摘要，你觉得自己已经懂这个项目了。接下来让 AI 改那个批处理任务。AI 基于它读到的那份上下文，给你一个看起来合理的方案。改完跑通了，测试也过了。</p><p>然后上线，炸了。炸的是那段“// 不要删，某某对接方需要”的逻辑。</p><p>问题在哪里？不在 AI 的 80%。AI 在第一档那些步骤上做得都挺好，摘要也完整、代码也干净。问题在于忘了还有 20% 没被覆盖。 <strong>那 20% 是 AI 根本读不到的历史、默契、隐性约定</strong>。</p><p>用 AI 用得不好的工程师最常见的错误，就是把 80% 的完成度当成 100% 的完成度。</p><ol><li><p>AI 读完 README，你以为项目就懂了。但 README 里没写的那些事，AI 也不知道。</p></li><li><p>AI 画完架构图，你以为全貌都在手里了。但那几个“曾经踩过的坑”不会出现在架构图上。</p></li><li><p>AI 写完代码，你以为改造就做完了。但“这段上线后会不会影响另一个对接方”这件事，AI 给不了答案。</p></li></ol><p><strong>AI 覆盖不了的那 20%，如果你不主动去补，它就是 0。20% 的盲区，经常就是 100% 的事故</strong>。</p><h2 id="那-20-就是你的位置" tabindex="-1">那 20% 就是你的位置 <a class="header-anchor" href="#那-20-就是你的位置" aria-label="Permalink to &quot;那 20% 就是你的位置&quot;">​</a></h2><p>说到这儿，你应该能感觉到这门课要教的是什么了。 <strong>不是教你怎么让 AI 做 100% 的事</strong>。这做不到，也不应该追求。 <strong>是教你怎么把能交给 AI 的 80% 稳定交出去，同时把那 20% 自己守住</strong>。</p><p>这件事说起来简单，做起来要分成几件事。</p><ol><li><p><strong>你要知道哪些步骤属于哪一档</strong>。这张分工图要内化成你的本能。拿到任何一个新老项目、任何一个改造需求，你能瞬间判断：这一步 AI 冲在前面，那一步我要自己在前头、AI 辅助。</p></li><li><p><strong>第一档和第二档要快</strong>。AI 能做的事就让它做，别慢吞吞。不放手，AI 就没有价值。很多人用 Claude Code 用不出效率就是卡在这里。</p></li><li><p><strong>第三档要稳</strong>。该你判断的时候别想偷懒，别问 AI “你觉得呢”。你问 AI 它一定有答案，但那个答案没有承担责任，最后出事还是你的事。</p></li><li><p><strong>每一档之间的衔接要清晰</strong>。AI 做完初稿，什么时候该你接过来验？验完之后，什么时候再让 AI 继续？这个节奏是整门课最想教会你的事。后面的课程都在讲这件事。</p></li></ol><h2 id="ai-改变的不是链路-是节奏" tabindex="-1">AI 改变的不是链路，是节奏 <a class="header-anchor" href="#ai-改变的不是链路-是节奏" aria-label="Permalink to &quot;AI 改变的不是链路，是节奏&quot;">​</a></h2><p>最后想跟你说一件事。AI 没有改变九步链路本身，你该找人聊还得找人聊，该搭环境还得搭环境，该判断风险还得你判断， <strong>但 AI 改变了节奏</strong>。没有 AI 的时候，你读 README 要一小时，梳理接口要一下午，画架构图要一整天。整个了解阶段要一到两周。</p><p>有了 AI，这些步骤都能压缩到以分钟为单位。一个大周期下来，可能半天就进入改造阶段了。这是 AI 真正的价值： <strong>不是替代人，是把人从低信息含量的工作里解放出来，去做那些真正需要人的事</strong>。</p><p>那些真正需要人的事是什么？就是第二档里你要做的那些判断、第三档里你要守的那些边界。AI 能做的事你交出去，节省下来的时间就能用在第三档上。你对项目理解更深，你对边界更清醒，你给 AI 的上下文更准，这是一个正循环。</p><p>不会用 AI 的工程师，是把所有时间都花在第一档那些事上，累死累活也谈不上效率。用错 AI 的工程师，是让 AI 把第一、第二、第三档都一起做了，出事再回头。 <strong>用对 AI 的工程师，是把第一档的速度和第三档的稳当都兼顾住</strong>。这门课就是要把你训练成用对 AI 的工程师。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一讲给了你一张人机分工图。</p><p>九步链路按 AI 能承担的比例分三档。</p><p>第一档 AI 主导做 80%，翻资料、浏览代码结构、访接口都在这里，放手让 AI 做就行。</p><p>第二档人机对半 AI 做 50%，找人聊、搭环境、深挖、画链路、动手改都在这里，整门课大部分功夫花在这一档。</p><p>第三档人主导 AI 做 20% 或更少，判断代码能不能动、对接方是谁、最终验收、上线风险识别都在这里。</p><p>记住那句话： <strong>20% 的盲区，经常就是 100% 的事故</strong>。AI 做不到的那 20%，你不主动补，它就是 0。</p><p>下一讲我们展开三层控制：理解、约束、验证。光有分工图还不够，要让 AI 在第一档和第二档里真正可信地帮你干活，还需要一套让它不乱来的框架。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>拿你手上正在维护的那个项目，按九步走一遍。对照每一步，写一写：如果现在让 Claude Code 做，它能做多少？剩下的是什么？剩下的那部分目前存在哪儿？(你脑子里？文档里？某个同事的脑子里？)</p></li><li><p>回想你最近一次用 Claude Code 改老项目的经历，如果改造结果有问题，问题发生在九步里的哪一步？那一步你把它归为哪一档？归错档了没？</p></li></ol><p>欢迎在评论区把你的答案写出来。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>',51)])])}const u=l(o,[["render",r]]);export{h as __pageData,u as default};
